<template><view class="page"><view class="notice">仅展示用户主动授权给你的范围；用户撤销后会立即失效。</view><navigator v-for="item in list" :key="item.authorizationId" :url="'/pages/jk/health/authorizedData?ownerUserId='+item.ownerUserId+'&name='+encodeURIComponent(item.ownerName||'用户')" class="card"><view><b>{{item.ownerName||'用户'}}</b><text>{{item.ownerPhoneMasked}}</text></view><view><text>{{item.scopeCodes}}</text><text>查看 ›</text></view></navigator><view v-if="!list.length" class="empty">暂无用户授权</view></view></template><script>import{getAuthorizedHealthOwners}from'@/api/health.js';export default{data(){return{list:[]}},onShow(){getAuthorizedHealthOwners().then(r=>this.list=(r&&r.data)||r||[]).catch(()=>this.list=[])} }</script><style lang="scss" scoped>.page{min-height:100vh;background:#f6f7f8;padding:24rpx}.notice{padding:22rpx;background:#fff7df;color:#9a6c16;border-radius:18rpx;margin-bottom:20rpx;font-size:24rpx}.card{display:flex;justify-content:space-between;background:#fff;border-radius:18rpx;padding:26rpx;margin-bottom:16rpx}.card text{display:block;color:#999;font-size:23rpx;margin-top:8rpx}.empty{text-align:center;padding:100rpx;color:#aaa}</style>